    type: "animal-habitat",
    parent: "PE-TUM",
    coords: [-80.4000, -3.4166],
    name: {
      de: "Mangrovenwälder von Tumbes",
      hu: "Tumbes Mangroveerdők",
      ro: "Mangrovele din Tumbes",
      en: "Tumbes Mangroves Sanctuary"},
    description: {
      de: "Ein einzigartiges Ökosystem im Norden Perus, in dem sich Süßwasser mit dem Meer mischt und Krokodile beheimatet sind.",
      hu: "Egyedülálló ökoszisztéma Észak-Peruban, ahol az édesvíz keveredik a tengerrel, és krokodiloknak ad otthont.",
      ro: "Un ecosistem unic în nordul statului Peru, unde apa dulce se amestecă cu marea și găzduiește crocodili.",
      en: "A unique ecosystem in northern Peru where freshwater mixes with the sea, home to American crocodiles.",
      es: "Un ecosistema único en el norte de Perú, donde el agua dulce se mezcla con el mar y que alberga cocodrilos.",
      pt: "Um ecossistema único no norte do Peru, onde a água doce se mistura com o mar e que abriga crocodilos.",
      fr: "Un écosystème unique dans le nord du Pérou, où l'eau douce se mélange à la mer et qui abrite des crocodiles.",
    },
    descriptionAdvanced: {
      en: "The Manglares de Tumbes National Sanctuary, located on the far northern coast of Peru, protects the country's most significant mangrove ecosystem. This unique environment, where fresh river water meets the salt water of the Pacific, is a labyrinth of tidal channels and tangled roots that serve as a vital nursery for marine life. It is famous for its 'Black Scallops' (conchas negras) and the formidable American crocodile, which finds one of its last remaining habitats in Peru here. The sanctuary is a haven for birdwatchers, with over 140 species of birds, including the rare mangrove warbler. Navigating its calm waters by boat offers a serene journey through a world of emerald green, where the life of the sea and the forest are inextricably linked.",
      de: "Das Santuario Nacional Manglares de Tumbes im äußersten Norden Perus schützt ein außergewöhnliches Ökosystem, das an der Mündung des Tumbes-Flusses in den Pazifik entstanden ist. Dieses Schutzgebiet erstreckt sich über fast 3.000 Hektar und ist geprägt von dichten Mangrovenwäldern, deren Wurzeln ein Labyrinth im Brackwasser bilden. Es ist der einzige Ort in Peru, an dem das seltene Spitzkrokodil (Crocodylus acutus) in freier Wildbahn überlebt hat. Die Mangroven dienen als biologische Kinderstube für zahlreiche Meeresbewohner, darunter die für die lokale Gastronomie berühmten schwarzen Muscheln (Conchas Negras) und verschiedene Krabbenarten. Für Ornithologen ist das Reservat ein Paradies, da über 140 Vogelarten hier nisten oder rasten. Besucher können das Gebiet mit kleinen Booten erkunden, um die Stille der Natur und die faszinierende Anpassungsfähigkeit der Pflanzen an den wechselnden Salzgehalt zu erleben. Der Schutz dieses Gebiets ist entscheidend für den Erhalt der peruanischen Küstenbiodiversität.",
      hu: "A Tumbes Mangroveerdők Nemzeti Szentélye Peru északi határán fekszik, és az ország egyik legkülönlegesebb természeti kincse. Ez a közel 3000 hektáros terület ott alakult ki, ahol az édesvizű folyók találkoznak a Csendes-óceán sós vizével, létrehozva egy szövevényes vízi labirintust. A terület legfontosabb lakója az amerikai krokodil, amelynek Peruban ez az utolsó természetes élőhelye. A mangrovék sűrű gyökérzete nemcsak a partvonalat védi az eróziótól, hanem biztonságos bölcsőként is szolgál számtalan hal-, rák- és kagylófaj számára. Különösen híresek az itt gyűjtött fekete kagylók, amelyek a helyi gasztronómia alapkövei. A madárvilág rendkívül gazdag, több mint 140 faj, köztük gémek és fregattmadarak figyelhetők meg a fák lombjai között. A látogatók csónakkal járhatják be a keskeny csatornákat, megtapasztalva azt az érintetlen vadont, amely a trópusi és a tengeri ökoszisztémák határán jött létre.",
      ro: "Sanctuarul Național Manglares de Tumbes este o rezervație naturală spectaculoasă situată în nordul extrem al Peru-lui, la granița cu Ecuador. Acest ecosistem protejat se întinde pe aproximativ 2.972 de hectare și este format dintr-o rețea complexă de canale inundabile și păduri de mangrove care se dezvoltă la întâlnirea apelor dulci ale râului Tumbes cu Oceanul Pacific. Este singurul loc din Peru unde poate fi observat crocodilul american în habitatul său natural, o specie aflată în pericol de dispariție. Mangrovele joacă un rol ecologic fundamental, servind drept pepinieră pentru numeroase specii marine și oferind adăpost pentru peste 140 de specii de păsări. Economia locală depinde în mare măsură de acest ecosistem, aici fiind recoltate celebrele scoici negre (Conchas Negras). O excursie cu barca prin labirintul de rădăcini aeriene oferă o experiență unică de observare a biodiversității, într-un peisaj unde verdele intens al vegetației se împletește cu reflexiile apei sub soarele tropical.",
      es: "Los Manglares de Tumbes son un elemento notable de la geografía y cultura peruana. Un ecosistema único en el norte de Perú donde se mezcla agua dulce y salada. Tiene una superficie de 2.972 hectáreas. Hábitat vital para las conchas negras. Esta área protegida forma parte de la rica biodiversidad de Perú, desde los Andes hasta el Amazonas. Como muchos sitios significativos en Perú, este lugar une características regionales con una importancia nacional. Contribuye al perfil multifacético de Perú, desde Machu Picchu hasta el Amazonas.",
      pt: "Os Manguezais de Tumbes são um elemento notável da geografia e cultura peruana. Um ecossistema único no norte do Peru, onde a água doce se mistura com o mar. Possui uma área de 2.972 hectares. Habitat importante para os bivalves negros. Esta área protegida faz parte da rica vida selvagem do Peru, dos Andes à Amazônia. Como muitos lugares significativos no Peru, este local une peculiaridades regionais com importância global. Assim, este local contribui para o perfil diversificado do Peru.",
      fr: "Les Mangroves de Tumbes sont un élément remarquable de la géographie et de la culture péruviennes. Un écosystème unique dans le nord du Pérou, où l'eau douce se mélange à la mer et qui abrite des crocodiles. Superficie de 2 972 hectares. Habitat crucial pour les arches noires (coquillages). Cette zone protégée fait partie de la riche faune et flore du Pérou, des Andes à l'Amazonie. Comme de nombreux sites importants au Pérou, ce lieu allie des particularités régionales à une importance globale. Il contribue au profil varié du Pérou, de l'héritage inca au bassin amazonien.",
    },
