    factsAdvanced: {
      de: ["Das Weingut wurde um das Jahr 1540 gegründet.", "Tacama umfasst eine Fläche von etwa 250 Hektar Rebfläche.", "Die ersten Reben stammten direkt von den Kanarischen Inseln.", "Es ist das erste Weingut in Peru, das französische Önologen einstellte.", "Tacama produziert jährlich über eine Million Liter Wein und Pisco.", "Die Kellerei befindet sich etwa 300 Kilometer südlich von Lima."],
      hu: ["A borászatot 1540 körül alapították a gyarmati időkben.", "A Tacama birtok körülbelül 250 hektárnyi szőlőültetvénnyel rendelkezik.", "Az első szőlőtőkéket a Kanári-szigetekről szállították ide.", "Ez volt az első perui borászat, amely francia borászokat alkalmazott.", "Évente több mint egymillió liter bort és piscót állítanak elő.", "A birtok Ica városától mindössze néhány kilométerre található."],
      ro: ["Podgoria a fost înființată în jurul anului 1540 de Francisco de Carabantes.", "Tacama se întinde pe o suprafață de aproximativ 250 de hectare.", "Primele vițe de vie au fost aduse direct din Insulele Canare.", "A fost prima cramă din Peru care a implementat tehnologia franceză modernă.", "Producția anuală depășește un milion de litri de băuturi alcoolice.", "Este situată la o altitudine de 400 de metri în Valea Ica."],
      en: ["The vineyard was established around 1540 during the colonial period.", "Tacama covers an area of approximately 250 hectares of cultivated land.", "The original vines were imported directly from the Canary Islands.", "It was the first Peruvian winery to employ professional French enologists.", "The estate produces over one million liters of wine and Pisco annually.", "It is located in the Ica Valley, roughly 300 kilometers south of Lima."],
      es: ["Uno de los viñedos más antiguos de Sudamérica, que produce vino y pisco en el fértil oasis de Ica.", "Situado en el territorio de la República del Perú.", "Incrustado entre la cordillera de los Andes, el desierto costero y la cuenca del Amazonas.", "Juega un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Um dos vinhedos mais antigos da América do Sul, que produz vinho e pisco no fértil oásis de Ica.", "Localizado no território da República do Peru.", "Inserido entre a cordilheira dos Andes, o deserto costeiro e a bacia amazônica.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
      fr: ["L'un des plus anciens vignobles d'Amérique du Sud, produisant du vin et du pisco dans la fertile oasis d'Ica.", "Situé sur le territoire de la République du Pérou.", "Niché entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
    },
    image: "/poi-images/tacama-vineyard-life-v2.webp"
