    type: "kid-landmark",
    parent: "PE-LAL",
    coords: [-79.0333, -8.1166],
    name: {
      de: "Botanischer Garten von Trujillo",
      hu: "Trujillo Botanikus Kert",
      ro: "Grădina Botanică din Trujillo",
      en: "Trujillo Botanical Garden"},
    image: "/poi-images/trujillo-botanical-garden-life-v2.webp",
    description: {
      de: "Ein ruhiger städtischer Garten im Herzen von Trujillo, der heimische Pflanzen und kleine Tiere wie Pfauen beherbergt.",
      hu: "Nyugodt városi kert Trujillo szívében, amely őshonos növényeknek és kisebb állatoknak, például páváknak ad otthont.",
      ro: "O grădină urbană liniștită în inima orașului Trujillo, care găzduiește plante native și animale mici, precum păuni.",
      en: "A tranquil urban garden in the heart of Trujillo that houses native plants and small animals like peacocks.",
      es: "Un tranquilo jardín urbano en el corazón de Trujillo que alberga plantas nativas y pequeños animales como pavos reales.",
      pt: "Um tranquilo jardim urbano no coração de Trujillo que abriga plantas nativas e pequenos animais como pavões.",
      fr: "Un jardin urbain paisible au cœur de Trujillo, abritant des plantes indigènes et de petits animaux comme des paons.",
    },
    descriptionAdvanced: {
      de: "Der Botanische Garten von Trujillo ist eine grüne Oase im Herzen der „Stadt des ewigen Frühlings“ im Norden Perus. Die Anlage wurde geschaffen, um die lokale Flora zu erhalten und den Bürgern einen Ort der Bildung und Erholung zu bieten. Der Garten beherbergt eine beeindruckende Sammlung von über 200 Pflanzenarten, darunter zahlreiche Kakteen, Bromelien und Orchideen sowie monumentale Bäume wie den Algarrobo. Ein besonderes Augenmerk liegt auf den Heilpflanzen, die in der traditionellen Medizin der peruanischen Nordküste verwendet werden. Die Gestaltung des Gartens umfasst kleine Teiche, schattige Wege und Volieren mit lokalen Vogelarten, was ihn zu einem wichtigen Rückzugsort für die städtische Biodiversität macht. Er dient als lebendiges Labor für Studenten und Forscher, die sich mit Botanik und Ökologie beschäftigen. Der Garten ist ein Beweis für das Engagement der Stadt Trujillo für den Umweltschutz und die Verbesserung der Lebensqualität in einem urbanen Umfeld.",
      hu: "Trujillo botanikus kertje egy zöld oázis az „örök tavasz városának” szívében, Peru északi részén. A kertet azzal a céllal hozták létre, hogy megőrizzék a helyi flórát, és oktatási, valamint kikapcsolódási lehetőséget biztosítsanak a lakosság számára. A területen több mint 200 növényfajból álló gyűjtemény található, köztük számos kaktusz, bromélia és orchidea, valamint olyan monumentális fák, mint az algarrobo. Különös figyelmet fordítanak a perui északi partvidék hagyományos gyógyászatában használt gyógynövények bemutatására. A kert kialakítása kisméretű tavakat, árnyékos ösvényeket és helyi madárfajokat bemutató röptetőket foglal magában, így fontos menedékhely a városi élővilág számára is. Egyetemi hallgatók és kutatók számára élő laboratóriumként szolgál a botanikai és ökológiai tanulmányokhoz. A kert Trujillo elkötelezettségét jelképezi a környezetvédelem és a városi életminőség javítása iránt.",
      ro: "Grădina Botanică din Trujillo este o oază de verdeață situată în centrul „Orașului Primăverii Eterne” din nordul Perului. Această facilitate a fost creată pentru a conserva flora locală și pentru a oferi cetățenilor un spațiu dedicat educației ecologice și relaxării. Grădina găzduiește o colecție impresionantă de peste 200 de specii de plante, incluzând numeroase varietăți de cactuși, bromelii și orhidee, precum și arbori monumentali precum Algarrobo. O secțiune specială este dedicată plantelor medicinale utilizate în medicina tradițională de pe coasta de nord a Perului. Designul grădinii include mici iazuri, alei umbrite și voliere cu păsări locale, transformând-o într-un refugiu important pentru biodiversitatea urbană. Servește ca un laborator viu pentru studenții și cercetătorii care studiază botanica și ecologia. Grădina reflectă angajamentul orașului Trujillo pentru protecția mediului și îmbunătățirea calității vieții într-un context urban dens.",
      en: "The Trujillo Botanical Garden is a lush green oasis located in the heart of the 'City of Eternal Spring' in northern Peru. This facility was established to preserve local flora and provide citizens with a space for environmental education and recreation. The garden houses an impressive collection of over 200 plant species, including numerous varieties of cacti, bromeliads, and orchids, as well as monumental trees like the Algarrobo. A special focus is placed on medicinal plants used in the traditional medicine of the Peruvian north coast. The garden's layout includes small ponds, shaded walkways, and aviaries featuring local bird species, making it an important refuge for urban biodiversity. It serves as a living laboratory for students and researchers focused on botany and ecology. The garden stands as a testament to Trujillo's commitment to environmental conservation and the enhancement of urban quality of life.",
      es: "El Jardín Botánico de Trujillo es un elemento notable de la geografía y cultura peruana. Un tranquilo jardín urbano en el corazón de Trujillo que alberga plantas nativas y pequeños animales como pavos reales. Considerado el pulmón verde de la ciudad. Ofrece educación ambiental para niños. Esta área protegida forma parte de la rica flora y fauna de Perú, desde los Andes hasta la selva amazónica y la costa del Pacífico. Como muchos lugares significativos de Perú, este sitio combina particularidades regionales entre el Pacífico, los Andes y la Amazonía con una importancia global. Así, este lugar contribuye al perfil diverso de Perú, desde el legado inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "O Jardim Botânico de Trujillo é um elemento notável da geografia e cultura peruana. Um tranquilo jardim urbano no coração de Trujillo que abriga plantas nativas e pequenos animais como pavões. Considerado o pulmão verde da cidade. Oferece educação ambiental para crianças. Esta área protegida faz parte da rica fauna e flora do Peru, desde os Andes até a floresta amazônica e a costa do Pacífico. Como muitos lugares significativos no Peru, este local combina peculiaridades regionais entre o Pacífico, os Andes e a Amazônia com importância abrangente. Assim, este lugar contribui para o perfil versátil do Peru, desde a herança inca e Machu Picchu até Lima e a bacia amazônica.",
      fr: "Le jardin botanique de Trujillo est un élément remarquable de la géographie et de la culture péruviennes. Un jardin urbain paisible au cœur de Trujillo, abritant des plantes indigènes et de petits animaux comme des paons. Considéré comme le poumon vert de la ville. Il propose une éducation environnementale pour les enfants. Cette aire protégée fait partie de la riche faune et flore du Pérou, des Andes à la forêt amazonienne jusqu'à la côte pacifique. Comme de nombreux sites importants au Pérou, ce lieu combine des particularités régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Ainsi, ce lieu contribue au profil diversifié du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
