    image: "/poi-images/ausangate-alpaca-farms-life-v2.webp",
    description: {
      de: "Die hochgelegenen Weiden rund um den heiligen Berg Ausangate sind das Herzstück der peruanischen Alpaka-Zucht.",
      hu: "A szent hegy, az Ausangate körüli magaslati legelők a perui alpakatenyésztés központja.",
      ro: "Pășunile la mare altitudine din jurul muntelui sacru Ausangate sunt centrul creșterii de alpaca din Peru.",
      en: "The high-altitude pastures surrounding the sacred Ausangate mountain are the heartland of Peruvian alpaca breeding.",
      es: "Los pastos de altura alrededor de la montaña sagrada Ausangate son el corazón de la cría de alpacas en Perú.",
      pt: "As pastagens de alta altitude ao redor da montanha sagrada Ausangate são o coração da criação de alpacas no Peru.",
      fr: "Les pâturages d'altitude autour de la montagne sacrée Ausangate sont le cœur de l'élevage d'alpagas au Pérou.",
    },
    descriptionAdvanced: {
      de: "Die Alpakaherden am Fuße des Ausangate-Massivs in der Region Cusco repräsentieren eine jahrtausendealte Tradition der andinen Viehzucht. Der Ausangate ist mit 6.384 Metern einer der heiligsten Berge der Inka und bildet das Zentrum einer Region, in der das Leben noch stark von der Alpakazucht bestimmt wird. Die Tiere weiden in Höhenlagen zwischen 4.000 und 5.000 Metern auf kargen Hochlandwiesen, den sogenannten Bofedales. Alpakas werden vor allem wegen ihrer hochwertigen Wolle gezüchtet, die für ihre Weichheit, Wärme und Widerstandsfähigkeit weltweit geschätzt wird. Die lokalen Gemeinschaften haben komplexe Zuchttechniken entwickelt, um verschiedene natürliche Farbtöne zu erhalten, ohne auf künstliche Farbstoffe angewiesen zu sein. Die jährliche Schur ist ein wichtiges kulturelles Ereignis, das oft mit religiösen Ritualen zum Schutz der Tiere einhergeht. Diese nachhaltige Form der Landwirtschaft schützt das empfindliche Ökosystem der Hochanden und sichert das Überleben der indigenen Kultur. Für Wanderer bietet der Anblick tausender Alpakas vor den schneebedeckten Gipfeln des Vilcanota-Gebirges ein unvergleichliches Erlebnis.",
      hu: "Az Ausangate-masszívum lábánál, Cusco régióban élő alpaka-nyájak az andoki állattenyésztés több ezer éves hagyományát képviselik. Az Ausangate 6384 méteres magasságával az inkák egyik legszentebb hegye, és egy olyan vidék központja, ahol az életet ma is az alpakatenyésztés határozza meg. Az állatok 4000 és 5000 méter közötti magasságban legelnek a „bofedales”-nek nevezett vizenyős magashegyi réteken. Az alpakákat elsősorban kiváló minőségű gyapjújukért tartják, amelyet puhasága, hőtartó képessége és tartóssága miatt világszerte nagyra értékelnek. A helyi közösségek bonyolult tenyésztési technikákat fejlesztenek ki, hogy mesterséges festékek nélkül is különböző természetes színárnyalatokat kapjanak. Az éves nyírás fontos kulturális esemény, amelyet gyakran az állatok védelmét szolgáló vallási rituálék kísérnek. Ez a fenntartható mezőgazdasági forma védi a Magas-Andok érzékeny ökoszisztémáját és biztosítja az őshonos kultúra fennmaradását. A Vilcanota-hegység hófödte csúcsai előtt legelésző több ezer alpaka látványa felejthetetlen élményt nyújt a túrázóknak.",
      ro: "Turmele de alpaca de la poalele masivului Ausangate, în regiunea Cusco, reprezintă o tradiție milenară a zootehniei andine. Ausangate, cu o înălțime de 6.384 de metri, este unul dintre cei mai sacri munți (Apu) pentru incași și centrul unei regiuni unde viața depinde în totalitate de creșterea alpacelor. Animalele pasc la altitudini cuprinse între 4.000 și 5.000 de metri pe pajiștile montane umede cunoscute sub numele de „bofedales”. Alpacele sunt crescute în principal pentru lâna lor de înaltă calitate, apreciată la nivel global pentru finețea, căldura și rezistența sa. Comunitățile locale au dezvoltat tehnici complexe de selecție pentru a obține o varietate de culori naturale, fără a utiliza vopsele artificiale. Tunsul anual este un eveniment cultural major, însoțit adesea de ritualuri religioase dedicate protecției animalelor. Această formă sustenabilă de agricultură protejează ecosistemul fragil al Anzilor înalți și asigură supraviețuirea culturii indigene Quechua. Vederea miilor de alpace pe fundalul vârfurilor înzăpezite ale cordilierei Vilcanota oferă o experiență vizuală unică pentru exploratori.",
      en: "The alpaca herds at the foot of the Ausangate massif in the Cusco region represent a millennia-old tradition of Andean pastoralism. At 6,384 meters, Ausangate is one of the most sacred mountains (Apu) to the Inca and remains the heart of a region where life is still fundamentally shaped by alpaca breeding. These animals graze at high altitudes between 4,000 and 5,000 meters on specialized wetland meadows known as bofedales. Alpacas are primarily raised for their high-quality fiber, which is prized worldwide for its softness, thermal properties, and durability. Local Quechua-speaking communities have developed complex breeding techniques to maintain dozens of natural color shades without the need for artificial dyes. The annual shearing season is a significant cultural event, often accompanied by ancient religious rituals intended to protect the herds. This sustainable form of high-altitude farming helps preserve the delicate Andean ecosystem and supports the cultural continuity of indigenous mountain communities. For travelers, the sight of thousands of alpacas against the snowy backdrop of the Vilcanota range is a definitive Andean experience.",
      es: "Los Rebaños de alpacas en el Ausangate son un elemento notable de la geografía y cultura peruanas. Los pastos de altura alrededor de la montaña sagrada Ausangate son el corazón de la cría de alpacas en Perú. La lana de alpaca es valorada en todo el mundo por su suavidad. La cría está profundamente arraigada en la cultura quechua. Esta área protegida forma parte de la rica flora y fauna de Perú, desde los Andes hasta la selva amazónica y la costa del Pacífico. Como muchos lugares importantes de Perú, este sitio combina características regionales entre el Pacífico, los Andes y la Amazonía con un significado global. Así, este lugar contribuye al perfil polifacético de Perú, desde el legado inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "Os Rebanhos de alpacas no Ausangate são um elemento notável da geografia e cultura peruanas. As pastagens de alta altitude ao redor da montanha sagrada Ausangate são o coração da criação de alpacas no Peru. A lã de alpaca é valorizada em todo o mundo pela sua suavidade. A criação está profundamente enraizada na cultura quéchua. Esta área protegida faz parte da rica flora e fauna do Peru, desde os Andes até a floresta amazônica e a costa do Pacífico. Como muitos lugares importantes no Peru, este local combina características regionais entre o Pacífico, os Andes e a Amazônia com um significado abrangente. Assim, este local contribui para o perfil multifacetado do Peru, desde o legado inca e Machu Picchu até Lima e a bacia amazônica.",
      fr: "Les Troupeaux d'alpagas à l'Ausangate sont un élément remarquable de la géographie et de la culture péruviennes. Les pâturages d'altitude autour de la montagne sacrée Ausangate sont le cœur de l'élevage d'alpagas au Pérou. La laine d'alpaga est appréciée dans le monde entier pour sa douceur. L'élevage est profondément enraciné dans la culture quechua. Cette zone protégée fait partie de la riche flore et faune du Pérou, des Andes à la forêt amazonienne en passant par la côte pacifique. Comme beaucoup de lieux importants au Pérou, ce site combine des caractéristiques régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Ainsi, ce lieu contribue au profil diversifié du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
