      hu: ["Az Ausangate 6384 méterével Peru ötödik legmagasabb csúcsa.", "Az alpakák a tevefélék családjába tartoznak és az Andokban őshonosak.", "Az alpaka gyapjú több mint 20 természetes színárnyalatban létezik.", "Az állatok gyakran 4500 méter feletti magasságban legelnek.", "Az alpaka rostja háromszor melegebb a juhgyapjúnál.", "Az Ausangate környéki közösségek őrzik a prekolumbán szövési technikákat."],
      ro: ["Ausangate este al cincilea cel mai înalt munte din Peru, având 6.384 metri.", "Alpacele fac parte din familia camelidelor și sunt native din Anzi.", "Lâna de alpaca există în peste 20 de nuanțe naturale diferite.", "Turmele pasc frecvent la altitudini ce depășesc 4.500 de metri.", "Fibra de alpaca este de trei ori mai călduroasă decât lâna de oaie.", "Comunitățile din jurul Ausangate păstrează tehnici de țesut precolumbiene."],
      en: ["Ausangate is the fifth-highest peak in Peru, reaching 6,384 meters.", "Alpacas are members of the camelid family and are native to the high Andes.", "Alpaca fiber occurs naturally in more than 20 distinct color shades.", "Herds are commonly grazed at elevations exceeding 4,500 meters above sea level.", "Alpaca fiber is approximately three times warmer than standard sheep's wool.", "Communities near Ausangate still use pre-Columbian weaving and dyeing techniques."],
      es: ["Los pastos de altura alrededor de la montaña sagrada Ausangate son el corazón de la cría de alpacas en Perú.", "Se encuentra en el territorio de la República del Perú.", "Situado entre la cordillera de los Andes, el desierto costero y la cuenca del Amazonas.", "Juega un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
